import {createPresetId} from './preset-data.mjs';
import {layoutContext,layoutPresetSnapshot,mappingKey} from './layout-preset-data.mjs';
// Shares the app's revision-protected preset API; layouts use a separate scope.
export function createLayoutPresets({refresh,notify,request=globalThis.fetch}){
 let items=[],defaults={},defaultsRevision=0,status='idle',error='',busy=false;
 async function api(path,options){const response=await request(path,options);let data;try{data=await response.json();}catch{throw Error('Saved layouts are unavailable. Please retry.');}if(!response.ok)throw Error(data.error||'Could not access saved layouts.');return data;}
 async function init(){if(status==='loading')return;status='loading';error='';try{const [layouts,settings]=await Promise.all([api('/api/layout-presets'),api('/api/layout-defaults')]);items=layouts.presets;defaults=settings.defaults||{};defaultsRevision=settings.revision||0;status='ready';}catch(e){status='error';error=e.message;}refresh();}
 async function save(name,state,config,id=null,{quiet=false}={}){if(busy)return null;let snapshot;try{snapshot=layoutPresetSnapshot(name,{context:layoutContext(state),config});}catch(e){error=e.message;notify(error);refresh();return null;}
 const old=id?items.find(p=>p.id===id):null,recordId=old?.id||createPresetId();busy=true;error='';refresh();
 try{const {preset}=await api('/api/layout-presets/'+recordId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:snapshot.name,state:snapshot,revision:old?.revision||0})});items=[...items.filter(p=>p.id!==recordId),preset].sort((a,b)=>a.name.localeCompare(b.name));status='ready';if(!quiet)notify(`Saved layout “${preset.name}”.`);return preset;}catch(e){error=e.message;notify(error);return null;}finally{busy=false;refresh();}}
 async function setDefault(id,state){if(busy)return false;const preset=items.find(p=>p.id===id),key=mappingKey(state);if(!preset||mappingKey(preset.state.context)!==key){error='Save a layout for the selected temperament before setting its default.';notify(error);refresh();return false;}if(defaults[key]===id){notify(`Updated the default layout for ${state.name}.`);return true;}busy=true;error='';refresh();try{const result=await api('/api/layout-defaults',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({mappingKey:key,layoutId:id,revision:defaultsRevision})});defaults=result.defaults||{};defaultsRevision=result.revision||0;notify(`“${preset.name}” is now the default layout for ${state.name}.`);return true;}catch(e){error=e.message;try{const latest=await api('/api/layout-defaults');defaults=latest.defaults||{};defaultsRevision=latest.revision||0;}catch{}notify(error);return false;}finally{busy=false;refresh();}}
 async function remove(id){const p=items.find(p=>p.id===id);if(busy||!p)return false;busy=true;error='';refresh();try{await api('/api/layout-presets/'+id+'?revision='+p.revision,{method:'DELETE'});items=items.filter(p=>p.id!==id);try{const latest=await api('/api/layout-defaults');defaults=latest.defaults||{};defaultsRevision=latest.revision||0;}catch{defaults=Object.fromEntries(Object.entries(defaults).filter(([,value])=>value!==id));}notify('Layout preset removed.');return true;}catch(e){error=e.message;notify(error);return false;}finally{busy=false;refresh();}}
 return {init,save,setDefault,remove,catalog:()=>({items,defaults,status,error,busy})};
}
